SELECT report_img.img
FROM report_img
WHERE report_img.report_id = #{reportId}
AND report_img.typeId = #{typeId}

SELECT report_img.img
FROM report_img
WHERE report_img.report_id = #{id}

SELECT report.*
FROM report
WHERE report.user_id = #{userId}

SELECT employee.orchard_id
FROM fruit.employee
WHERE employee.id = #{userId}

SELECT report.*
FROM fruit.report
WHERE report.user_id = #{empId}
  AND report.tree_id = #{treeId}
  AND report.type_id = #{typeId}
ORDER BY create_time DESC
LIMIT 1

SELECT employee.name
FROM fruit.employee
WHERE employee.id = #{userId}
